def read_publisher(rec):
    fields = (
        rec.get_fields('260')
        or rec.get_fields('264')[:1]
        or [rec.get_linkage('260', '880')]
    )
    if not fields:
        return
    publisher = []
    publish_places = []
    for f in fields:
        f.remove_brackets()
        contents = f.get_contents(['a', 'b'])
        if 'b' in contents:
            publisher += [x.strip(" /,;:") for x in contents['b']]
        if 'a' in contents:
            publish_places += [x.strip(" /.,;:") for x in contents['a'] if x]
    edition = {}
    if publisher:
        edition["publishers"] = publisher
    if len(publish_places) and publish_places[0]:
        edition["publish_places"] = publish_places
    return edition


def name_from_list(name_parts: list[str]) -> str:
    """Build a display name from MARC name subfields."""
    parts = [strip_foc(value.strip()).strip(' /,;:[]') for value in name_parts]
    return ' '.join(part for part in parts if part).removesuffix('.').strip(' /,;:[]')


