        return  # should at least be a name or title
    name = name_from_list(f.get_subfield_values(['a', 'b', 'c']))
    if 'd' in contents:
        author = pick_first_date(strip_foc(d).strip(',') for d in contents['d'])
        for key in ('birth_date', 'death_date'):
            if author.get(key):
                author[key] = author[key].removesuffix('.')
    author['name'] = name
    author['entity_type'] = 'person'
    subfields = [
        ('a', 'personal_name'),
        ('b', 'numeration'),
        ('c', 'title'),
        ('e', 'role'),
    ]
    for subfield, field_name in subfields:
        if subfield in contents:
            author[field_name] = name_from_list(contents[subfield])
    if 'q' in contents:
        author['fuller_name'] = ' '.join(contents['q'])
    if rec is not None:
        alternate_names = []
        for linkage in f.get_subfield_values('6'):
            # 880-01 and 100-01 may have an additional script code after '/'.
            if not linkage.startswith('880-'):
                continue
            target = tag + linkage[3:].split('/', 1)[0]
            for linked in rec.get_fields('880'):
                if any(
                    value.split('/', 1)[0] == target
                    for value in linked.get_subfield_values('6')
