                    alternate = name_from_list(
                        linked.get_subfield_values(['a', 'b', 'c'])
                    )
                    if alternate and alternate not in alternate_names:
                        alternate_names.append(alternate)
        if alternate_names:
            author['alternate_names'] = alternate_names
    return author


